import fs from 'node:fs';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';import {pathToFileURL} from 'node:url';
const out=process.env.OZ_QUALITY_PACKAGE_OUT;assert(out);const pkg=JSON.parse(fs.readFileSync(out+'/PACKAGE.json')),url=pathToFileURL(pkg.unpack+'/netlify/functions/flooring-assistant.mjs').href;
const code=`globalThis.fetch=()=>{throw Error('PAID_NETWORK_DENIED')};const fn=(await import(${JSON.stringify(url)})).default,origin='http://127.0.0.1:8840',req=b=>new Request(origin+'/api/flooring-assistant',{method:'POST',headers:{Origin:origin,'Content-Type':'application/json'},body:JSON.stringify({...b,aiUseAcknowledged:true})});const session=await(await fn(req({op:'session',requestId:'quality-bundle-session'}),{ip:'local'})).json();if(!session.sessionToken)throw Error('No session');let conversationToken='';const rows=[];for(const[i,message]of ['Avala Blackbutt supply only','And board size?','And finish?','Compare engineered timber and hybrid','Compare Avala Blackbutt and Avala Jarrah, excluding Artisan Tile','Can I upload a floor plan?'].entries()){const r=await fn(req({op:'message',requestId:'quality-bundle-'+i,message,pagePath:'/',sessionToken:session.sessionToken,conversationToken,history:[]}),{ip:'local'});const a=await r.json();if(r.status!==200||a.corpusVersion!==${JSON.stringify(pkg.corpusVersion)})throw Error('Bad bundle answer '+JSON.stringify(a));conversationToken=a.conversationToken||'';const text=a.segments.map(s=>s.text).join(' ');if(i<3&&a.enquiryContext?.product!=='Avala Blackbutt')throw Error('Lost exact handoff');if(i===1&&!text.includes('1524'))throw Error('Lost specification');if(i===2&&!text.includes('not available'))throw Error('Unknown finish invented');if(i===3&&a.sources.some(s=>!['/hybrid/','/engineered-timber-flooring/'].includes(s.href)))throw Error('Unrequested material');if(i===4&&(a.entityIds.length!==2||text.includes('Artisan Tile')))throw Error('Excluded third entity');if(i===5&&!text.includes('not send the files into this chat'))throw Error('Upload boundary');rows.push({message,status:r.status,reason:a.reason,corpusVersion:a.corpusVersion,context:a.enquiryContext,sources:a.sources,text});}console.log(JSON.stringify({status:'PASS',rows,paidCalls:0,networkAllowed:false}));`;
const r=spawnSync(process.execPath,['--input-type=module','-e',code],{cwd:pkg.unpack,env:{PATH:process.env.PATH,CONTEXT:'local',OZ_ASSISTANT_ENABLED:'true',OZ_ASSISTANT_MODE:'mock',OZ_ASSISTANT_ORIGIN:'http://127.0.0.1:8840',OZ_ASSISTANT_SIGNING_SECRET:'local-quality-bundle-test-not-a-real-secret-123456'},encoding:'utf8'});fs.writeFileSync(out+'/BUNDLE_MOCK.log',r.stdout+r.stderr);assert.equal(r.status,0,r.stderr);const result=JSON.parse(r.stdout);fs.writeFileSync(out+'/BUNDLE_MOCK.json',JSON.stringify(result,null,2));console.log({status:result.status,cases:result.rows.length,paidCalls:0});
